INSERT INTO `products` VALUES (999000.00,1,NULL,5,5,'2026-03-11 18:38:25.830408','2026-03-11 18:36:10.499303','Áo Sơ Mi Nam Tay Ngắn Form Ôm WS26SS11P-SD','Áo sơ mi với chất liệu 38% Polyester, 57.6% Rayon và 4.4% Spandex, vải mềm, nhẹ và có độ co giãn, mang lại cảm giác thoải mái khi mặc hằng ngày.\nThiết kế form ôm với thân áo ôm gọn, thu nhẹ từ ngực xuống eo, giúp tôn dáng nhưng không gây cảm giác bó sát. Vai áo vừa vặn, tay ngắn có độ rộng hợp lý, tạo tổng thể gọn gàng và cân đối.\nBề mặt vải có họa tiết caro nhỏ, đều và nhẹ, tạo điểm nhấn vừa phải cho tổng thể áo nhưng vẫn dễ mặc và dễ phối đồ.\nÁo có túi trước ngực tiện lợi, đường may được xử lý gọn gàng, giữ phom ổn định trong quá trình sử dụng.\nDễ phối cùng quần tây, khaki hoặc jeans, phù hợp cho đi làm, gặp gỡ hoặc mặc thường ngày với phong cách gọn gàng, lịch sự.'),(777000.00,1,NULL,6,7,'2026-03-11 19:31:19.303653','2026-03-11 19:26:26.667307','Áo Thun Polo Nữ FWKS25FH06C','Chất liệu: 100% Polyester – nhẹ, thoáng khí, thấm hút tốt và mau khô.\nThiết kế: Cổ bẻ truyền thống, tay ngắn, phom vừa vặn dễ mặc.\nMàu sắc: 5 màu basic - dễ phối cùng quần jeans, shorts và chân váy.\nPhù hợp: Đi làm, đi học, dạo phố hoặc hoạt động ngoài trời.\nĐiểm nhấn: Logo thêu tone-sur-tone tinh tế ở ngực trái.'),(666000.00,1,NULL,7,8,'2026-03-11 21:49:49.355294','2026-03-11 21:49:49.355294','Áo Blouse Nữ Cổ Vuông Không Tay – FWBL25FH04D','Thiết kế blouse không tay với cổ vuông thanh lịch, tôn phần vai và xương quai xanh một cách tinh tế.\n Phom dáng gọn gàng, đường cắt dứt khoát, mang lại vẻ ngoài hiện đại và chỉn chu\nChi tiết nắp túi trang trí phía trước tạo điểm nhấn nhẹ, tăng cảm giác thời trang nhưng không cầu kỳ.\nGam màu nâu trầm dễ ứng dụng, phù hợp phong cách minimal và môi trường công sở\nChất liệu 78% Polyester – 18% Rayon – 4% Spandex: bề mặt vải mịn, đứng phom vừa phải, có độ co giãn nhẹ giúp thoải mái khi mặc.\nDễ phối cùng quần tây, quần ống rộng hoặc chân váy để hoàn thiện nhiều phong cách khác nhau từ đi làm đến gặp gỡ hằng ngày.'),(50000.00,1,NULL,6,14,'2026-03-12 14:45:46.309929','2026-03-12 14:45:46.309929','Áo thun đen','Thiết kế polo cổ bẻ trẻ trung.\nMàu đen basic dễ phối đồ.\nForm dáng gọn gàng, tôn dáng.\nChất vải mềm, thoáng và co giãn nhẹ.\nPhù hợp nhiều dịp: đi học, đi làm, dạo phố.'),(123000.00,1,NULL,6,15,'2026-03-12 14:48:31.983953','2026-03-12 14:48:31.983953','áo thun trắng tay dài','Thiết kế tay dài thanh lịch.\nCổ nhún tạo điểm nhấn nữ tính.\nMàu trắng kem dễ phối đồ.\nChất vải mềm, co giãn và thoáng mát.\nPhù hợp đi làm, đi học, dạo phố.'),(349000.00,1,NULL,6,16,'2026-03-12 14:52:19.329865','2026-03-12 14:52:19.329865','Áo Thun Nữ Tay Ngắn Trẻ Trung','Được làm từ 65% Polyester và 35% Cotton, có tính năng kháng khuẩn, bền màu và mềm mại, mang lại sự thoải mái cho người mặc.\nThiết kế tay ngắn với form dáng cơ bản giúp tôn lên vóc dáng mà vẫn tạo sự thoải mái trong mọi hoạt động.\nÁo thun họa tiết loang màu tone màu xanh mát mẻ hợp với mùa hè.\nDễ dàng kết hợp với quần jeans, quần short, hoặc chân váy ngắn để tạo nên những bộ trang phục năng động và thời trang.'),(349000.00,1,NULL,6,17,'2026-03-12 14:54:09.725922','2026-03-12 14:54:09.725922','Áo Thun Nữ Tay Ngắn Năng Động','Áo thun Freelancer với chất liệu 100% cotton mềm mại, thoáng mát, có khả năng hút ẩm tốt mang lại cảm giác thoải mái khi sử dụng\nÁo tay ngắn, cổ tròn với thiết kế đơn giản có hình in phần mặt trước tạo điểm nhấn. Màu sắc hài hòa, bắt mắt giúp dễ dàng kết hợp với nhiều item khác nhau.\nCó thể phối áo cùng quần jean hoặc quần short để tạo nên outfit thời trang và cá tính'),(349000.00,1,NULL,6,18,'2026-03-12 14:57:07.128024','2026-03-12 14:57:07.128024','Áo Thun Nữ Form Vừa Tay Ngắn','Áo thun chất liệu 100% cotton mềm mại với form dáng thoải mái, dễ vận động\nÁo có tay ngắn, cổ tròn với hình in và thêu đặc sắc tạo điểm nhấn cho chiếc áo thun basic\nCó thể kết hợp áo cùng chân váy jean, quần jean hoặc quần short đều phù hợp'),(349000.00,1,NULL,6,19,'2026-03-12 14:59:14.152352','2026-03-12 14:59:14.152352','Áo Thun Nữ Vạt Chéo Cách Điệu','Áo thun chất liệu 100% Cotton mềm mại, thoáng mát với form vừa, tay ngắn, cổ tròn với phần vạt áo cách điệu cá tính và chữ in sắc nét, tinh tế.\nÁo phù hợp phối cùng quần jeans, khaki hoặc quần short mang tới vẻ ngoài trẻ trung và năng động\nPhù hợp mặc đi chơi, dã ngoại, dạo phố hoặc những hoạt động cần sự thoải mái.'),(399000.00,1,NULL,6,20,'2026-03-12 15:01:16.529975','2026-03-12 15:01:16.529975','Áo Thun Nữ Thêu Hoa','Chất liệu: 66.5% Cotton, 33.5% Polyester – mềm mại, thoáng mát, giữ form tốt và dễ chăm sóc.\nThiết kế cổ tròn basic mang đến sự năng động, dễ mặc trong nhiều hoàn cảnh.\nĐiểm nhấn thêu hoa nổi ở lưng áo – tạo nét nữ tính, nhẹ nhàng nhưng vẫn tinh tế.\nForm suông vừa vặn giúp tôn dáng, mang lại cảm giác thoải mái khi vận động.\nGam màu trắng thanh lịch – dễ phối với jeans, short hay chân váy, phù hợp từ đi học, đi làm đến dạo phố.'),(549000.00,1,NULL,7,21,'2026-03-12 15:03:54.716008','2026-03-12 15:03:54.716008','Áo Blouse Freelancer','Chất liệu 85% Tencel, 15% Nilon, mềm mại và thoáng mát, mang lại cảm giác dễ chịu suốt cả ngày.\nThiết kế cổ bẻ tròn duyên dáng, kết hợp hàng khuy tạo điểm nhấn tinh tế.\nTay lửng xếp ly tạo độ phồng nhẹ giúp tôn lên vẻ nữ tính và thanh thoát.\n Phom dáng suông nhẹ, dễ dàng kết hợp với nhiều trang phục, từ chân váy thanh lịch đến quần jeans hiện đại.\n Gam màu pastel nhẹ nhàng, phù hợp với phong cách thời trang tối giản và trang nhã.'),(399000.00,1,NULL,7,22,'2026-03-12 15:05:53.098248','2026-03-12 15:05:53.098248','Áo Blouse Cổ Trụ Freelancer','Chất liệu 94% Polyester, 6% Spandex mang lại độ mềm mại, ít nhăn và co giãn nhẹ, giúp nàng luôn thoải mái suốt ngày dài.\nThiết kế cổ trụ thanh lịch, tạo điểm nhấn trang nhã và tinh tế.\nPhom dáng suông nhẹ, che khuyết điểm khéo léo, tôn lên nét nữ tính và thanh thoát.\nGam màu trung tính dễ phối với quần âu, chân váy hay quần short, phù hợp cho cả môi trường công sở và dạo phố.'),(399000.00,1,NULL,7,23,'2026-03-12 15:07:33.016289','2026-03-12 15:07:33.016289','Áo Blouse Nữ Tay Bồng','Áo blouse với chất liệu Polyester hạn chế nhăn và có độ bền cao\nHọa tiết cá tính, độc đáo với phần vai có xếp ly và tay bồng cùng cổ tròn tạo nên nét nữ tính và điệu đà cho các quý cô\nCó thể phối áo cùng chân váy công sở hoặc quần tây tạo nên outfit vừa trẻ trung, vừa thanh lịch.'),(399000.00,1,NULL,7,24,'2026-03-12 15:09:43.238802','2026-03-12 15:09:43.238802','Áo Blouse Nữ Dáng Gile Thanh Lịch','Áo blouse được làm từ sự kết hợp giữa 75% Rayon và 25% Nylon, mang đến sự mềm mại, thoáng mát và độ bền cao.\nThiết kế dáng gile hiện đại, sát nách, mang phong cách hiện đại và thanh lịch.\nÁo dễ dàng để kết hợp với nhiều loại trang phục khác nhau, từ áo sơ mi, áo thun đến váy hoặc quần tây.'),(399000.00,1,NULL,7,25,'2026-03-12 15:11:41.086186','2026-03-12 15:11:41.086186','Áo Blouse Cổ Chữ V Nữ Tính','Áo blouse chất liệu polyester với phần tay xòe đắp chéo điệu đà và nữ tính\nÁo có cổ chữ V mang đến sự thanh thoát cho quý cô, phần eo với 2 nút cài bên ngoài và 2 nút cài bên trong giúp linh động điều chỉnh tùy theo kích thước, phần eo sau lưng được nhún thun góp phần tạo sự thoải mái cho người mặc\nCó thể phối áo cùng quần tây, quần jean, chân váy để tạo nên vẻ ngoài nữ tính và trẻ trung.'),(349000.00,1,NULL,7,26,'2026-03-12 15:13:47.785526','2026-03-12 15:13:47.785526','Áo Blouse Nữ Cách Điệu Thời Trang','Áo blouse với chất liệu 100% polyester có độ bền cao cùng kiểu dáng thanh lịch và thời trang\nÁo sát nách với phần tà áo lệch và chi tiết nhún eo cách điệu tạo điểm nhấn độc đáo\nCó thể phối áo cùng chân váy công sở hoặc quần tây để tạo nên những outfit chuyên nghiệp và chỉn chu'),(499000.00,1,NULL,9,27,'2026-03-12 15:17:17.388156','2026-03-12 15:17:17.388156','Chân Váy Nữ','Chất liệu: 100% polyester, thoáng khí, nhẹ nhàng và chống nhăn.\nThiết kế: Phom váy chữ A tôn dáng, dễ mặc, mang đến sự thanh lịch.\nChi tiết: Cạp cao giúp tạo hiệu ứng thon gọn, tăng phần nữ tính và tinh tế.'),(329000.00,1,NULL,9,28,'2026-03-12 15:18:50.188369','2026-03-12 15:18:50.188369','Chân Váy Nữ Thanh Lịch','Chân váy được làm từ 100% Polyester với độ bền cao và không bị nhăn.\nChân váy form chữ A, dài ngang gối giúp che khuyết điểm, váy thanh lịch nhưng vẫn giữ được nét nữ tính và duyên dáng.\nGam màu trơn đơn giản, dễ dàng mix & match với nhiều loại áo khác nhau như áo sơ mi, áo blouse, áo polo… tạo nên bộ trang phục chỉn chu phù hợp mặc đi làm, đi chơi hoặc dạo phố\n'),(499000.00,1,NULL,9,29,'2026-03-12 15:20:28.690203','2026-03-12 15:20:28.690203','Chân váy dáng xòe họa tiết nữ tính','Chân váy dài ngang gối, dáng xòe, dây kéo tinh tế và chắc chắn. Phần lai có rã bèo tạo sự bồng bềnh, uyển chuyển.\nChất liệu 100% polyester ít nhăn, bề mặt vải mát, dày dặn đứng form giúp bạn luôn cảm giác thoải mái và thoáng mát.\nMàu sắc và hoa văn tinh tế, sắc nét toát lên vẻ nữ tính nhưng không kém phần sang trọng, thanh lịch'),(550000.00,1,NULL,4,30,'2026-03-12 15:23:28.364965','2026-03-12 15:23:28.364965','Áo Polo Nam Form Vừa','Áo có chất liệu 100% Polyester, mang đến bề mặt vải nhẹ, thoáng khí và có độ bền cao. Chất liệu hỗ trợ khả năng thấm hút – thoát ẩm tốt, giúp cơ thể luôn khô thoáng trong suốt ngày dài.\nThiết kế form vừa hiện đại, dễ mặc và tôn dáng. Phần bo cổ và bo tay chắc chắn, giữ phom ổn định khi sử dụng. Điểm nhấn nổi bật nằm ở đường line phối màu chạy dọc thân trước, kết hợp logo JOHN HENRY in tinh tế, tạo hiệu ứng thị giác mới mẻ, mang lại vẻ ngoài năng động và cá tính.\nGam màu trung tính dễ phối – phù hợp cho nhiều bối cảnh: đi làm, dạo phố hay gặp gỡ bạn bè.'),(980000.00,1,NULL,4,31,'2026-03-12 15:25:22.930084','2026-03-12 15:25:22.930084','Áo Polo Nam Tay Ngắn Form Vừa','Áo polo sử dụng chất liệu 65% cotton và 35% polyester, vải mềm, thoáng và dễ chăm sóc, phù hợp cho nhu cầu mặc hằng ngày.\nThiết kế form vừa với thân áo suông nhẹ, không ôm sát cơ thể. Vai áo vừa vặn, tay áo có độ rộng hợp lý, giúp tổng thể gọn gàng và thoải mái khi vận động.\nBề mặt áo có họa tiết sọc ngang, bố trí đều, tạo điểm nhấn đặc sắc nhưng vẫn dễ mặc và dễ phối. Cổ polo được xử lý gọn, giữ phom ổn định trong quá trình sử dụng.\nDễ phối cùng quần jeans, khaki hoặc quần tây, phù hợp cho đi làm, đi chơi hoặc mặc thường ngày.'),(800000.00,1,NULL,4,32,'2026-03-12 15:27:06.703606','2026-03-12 15:27:06.703606','Áo Polo Nam Tay Ngắn Form Vừa','Áo polo với chất liệu 100% polyester, vải nhẹ, thoáng, ít nhăn và nhanh khô, phù hợp cho nhu cầu mặc hằng ngày.\nThiết kế form vừa với thân áo suông nhẹ, không ôm sát cơ thể. Vai áo vừa vặn, tay áo có độ rộng hợp lý, giúp tổng thể gọn gàng và thoải mái khi vận động.\nBề mặt áo có họa tiết đặc sắc, tạo điểm nhấn nhẹ nhưng vẫn dễ mặc. Cổ polo được xử lý gọn, giữ phom ổn định khi sử dụng.\nDễ phối cùng quần jeans, khaki hoặc quần tây, phù hợp cho đi làm, đi chơi hoặc mặc thường ngày.'),(700000.00,1,NULL,4,33,'2026-03-12 15:28:34.190391','2026-03-12 15:28:34.190391','Áo Polo Nam Tay Ngắn Form Vừa','Áo polo có chất liệu 72% cotton và 28% Sorona, vải mềm, thoáng và có độ co giãn nhẹ, mang lại cảm giác thoải mái khi mặc hằng ngày.\nThiết kế form vừa với thân áo suông nhẹ, không ôm sát cơ thể. Vai áo vừa vặn, tay áo có độ rộng hợp lý, giúp tổng thể gọn gàng và dễ vận động.\nChi tiết logo kết hợp in thêu trước ngực tạo điểm nhấn độc đáo, ấn tượng.\nGam màu trơn, dễ phối cùng quần jeans, khaki hoặc quần tây, phù hợp cho đi làm, đi chơi hoặc mặc thường ngày.'),(700000.00,1,NULL,5,34,'2026-03-12 15:31:14.282853','2026-03-12 15:31:14.282853','Áo Sơ Mi Nam Tay Ngắn ','Chất liệu 100% cotton mềm mại, thoáng mát và thấm hút mồ hôi mang lại cảm giác dễ chịu suốt cả ngày.\nForm áo tôn dáng, tay ngắn gọn gàng kết hợp họa tiết in trẻ trung cùng logo thêu ở túi áo tạo nên tổng thể hiện đại, nam tính.\nDễ dàng phối cùng quần jeans, khaki hoặc shorts, phù hợp với phong cách công sở năng động hoặc dạo phố cuối tuần.'),(800000.00,1,NULL,5,35,'2026-03-12 15:32:51.426635','2026-03-12 15:32:51.426635','Áo Sơ Mi Nam Tay Dài','Áo được làm từ 100% cotton, mang lại cảm giác mềm mại, thoáng mát và thoải mái suốt cả ngày dài.\nThiết kế tay dài với họa tiết caro nam tính, tạo nên phong cách lịch lãm và hiện đại.\nDễ dàng phối hợp với nhiều trang phục khác nhau, phù hợp cho phong cách công sở thanh lịch hoặc những dịp cần sự chỉn chu.'),(650000.00,1,NULL,5,36,'2026-03-12 15:39:59.976490','2026-03-12 15:39:59.976490','Áo Sơ Mi Nam Tay Ngắn','Với chất liệu 60% cotton 37% polyester 3% spandex, chiếc áo sơ mi mềm mại, thoáng khí mang lại cảm giác dễ chịu, thoáng mát cho người dùng.\nÁo có phối vải ở chân cổ và nẹp nút, form slimfit, tay ngắn tạo phong cách lịch sự nhưng không kém phần thoải mái.\nÁo có thể mix & match cùng quần tây, quần khaki, quần jeans tạo nên outfits lịch lãm và chỉn chu.'),(2100000.00,1,NULL,10,37,'2026-03-12 15:42:15.084636','2026-03-12 15:42:15.084636','Blazer Nam Form Ôm','Blazer có chất liệu 68% Polyester, 30% Viscose và 2% Spandex, bề mặt vải mịn, đứng phom và có độ co giãn nhẹ, mang lại cảm giác thoải mái khi mặc.\n\nThiết kế form ôm gọn gàng ở phần vai, ngực và thân áo, giúp tôn dáng nhưng không gây bó sát. Phom dáng hiện đại, phù hợp cho phong cách công sở chỉn chu hoặc smart–formal.\nChi tiết ve áo sắc nét, đường may chắc chắn, hoàn thiện tinh tế. Gam màu cơ bản dễ phối cùng quần tây, sơ mi hoặc áo thun.\nPhù hợp cho đi làm, gặp gỡ đối tác hoặc các dịp cần vẻ ngoài lịch lãm, chuyên nghiệp.'),(2100000.00,1,NULL,10,38,'2026-03-13 06:50:44.437736','2026-03-13 06:50:44.437736','Áo Blazer Nam Form Ôm','Với chất liệu 100% Wool cao cấp, blazer mang đến cảm giác mềm mại, thoáng mát và giữ form tốt.\nThiết kế form ôm hiện đại giúp tôn dáng và tạo vẻ ngoài gọn gàng, nam tính. Đường may sắc nét cùng tiết túi tinh tế mang đến tổng thể sang trọng, thanh lịch.\nGam màu trung tính dễ phối, dễ dàng kết hợp cùng sơ mi và quần tây, phù hợp cho môi trường công sở, gặp gỡ đối tác hay các sự kiện quan trọng.'),(2100000.00,1,NULL,10,39,'2026-03-13 06:52:32.865494','2026-03-13 06:52:32.865494','Áo Blazer Nam Form Ôm','Áo blazer có chất liệu 70% Polyester, 27% Viscose và 3% Spandex, mang lại bề mặt vải mềm, đứng phom và có độ co giãn nhẹ, giúp thoải mái khi mặc trong thời gian dài.\nThiết kế form ôm, gọn gàng ở phần vai và thân áo, tạo tổng thể chỉn chu và tôn dáng, phù hợp cho môi trường công sở hoặc các dịp cần sự trang trọng.\nÁo có họa tiết caro tinh tế với tông màu trầm, mang lại vẻ ngoài lịch lãm, nam tính.\nDễ phối cùng sơ mi trơn, quần tây hoặc khaki để hoàn thiện phong cách công sở và smart–casual.'),(1950000.00,1,NULL,10,40,'2026-03-13 06:54:38.013241','2026-03-13 06:54:38.013241','Áo Blazer Nam Form Vừa','Áo blazer với chất liệu 100% Polyester Nano, có độ bền cao, hạn chế nhăn hiệu quả và dễ dàng bảo quản. Chất liệu giúp áo giữ form dáng chuẩn, luôn phẳng phiu và mang lại cảm giác thoải mái suốt cả ngày.\nThiết kế form vừa đảm bảo sự thoải mái khi vận động, với đường may tinh tế và tỉ mỉ. Gam màu thanh lịch, dễ dàng phối hợp với nhiều kiểu trang phục khác nhau, từ áo sơ mi đến áo thun, mang đến vẻ ngoài lịch lãm và nam tính.\nLựa chọn hoàn hảo cho các sự kiện quan trọng, môi trường công sở hoặc những buổi gặp gỡ, dạo phố cùng bạn bè.'),(1950000.00,1,NULL,10,41,'2026-03-13 06:56:23.292092','2026-03-13 06:56:23.292092','Áo Blazer Nam Form Vừa','Chất liệu 100% Polyester Nano mang lại độ bền cao, hạn chế nhăn và giữ form tốt, giúp áo luôn giữ được vẻ chỉnh chu và gọn gàng suốt cả ngày dài.\nThiết kế form vừa tôn dáng, tạo nên phong thái lịch lãm và nam tính. Đường may tỉ mỉ cùng các chi tiết tinh tế mang lại diện mạo sang trọng và hiện đại.\nDễ dàng kết hợp với áo sơ mi hoặc áo thun, phối cùng quần tây hoặc jeans để hoàn thiện phong cách chuyên nghiệp nơi công sở hoặc phong cách năng động khi dạo phố.'),(2100000.00,1,NULL,10,42,'2026-03-13 06:57:59.739762','2026-03-13 06:57:59.739762','Áo Blazer Nam Tay Dài Form Ôm','Chất liệu 84% polyester, 15% viscose và 1% spandex giúp giữ form áo chuẩn, hạn chế nhăn, tạo cảm giác nhẹ và thoải mái khi mặc cả ngày.\nForm ôm tôn dáng với thiết kế tay dài cổ điển, đường cắt may tinh tế, vai áo vừa vặn – mang đến tổng thể lịch lãm, hiện đại và chuyên nghiệp.\nGam màu trung tính dễ phối cùng sơ mi, áo thun hoặc quần tây – phù hợp cho môi trường công sở, sự kiện hoặc những dịp cần sự chỉn chu.'),(790000.00,1,NULL,11,43,'2026-03-13 07:01:10.183036','2026-03-13 07:01:10.183036','Đầm Nữ Dáng Midi Smocked Thân Trên','Thiết kế dáng midi thanh lịch, chiều dài vừa phải, dễ ứng dụng trong nhiều hoàn cảnh từ đi làm đến dạo phố.\nPhần thân trên xử lý smocked (thun nhún) giúp ôm dáng tự nhiên, tôn vòng eo mà vẫn tạo cảm giác thoải mái khi mặc.\nCổ tròn sát nách tối giản, mang lại vẻ gọn gàng và hiện đại.\nPhần chân váy xòe nhẹ, tạo độ chuyển động mềm mại khi di chuyển, cân bằng tổng thể thiết kế.\nChất liệu: 56% Rayon – 34% Nilon – 10% Linen.\nDễ phối cùng sandal, giày bệt hoặc giày cao gót cho nhiều phong cách khác nhau.'),(749000.00,1,NULL,11,44,'2026-03-13 07:03:44.531782','2026-03-13 07:03:44.529740','Áo Đầm Cổ Thủy Thủ Xếp Ly','Thiết kế đầm dáng suông ngắn, cân bằng giữa nét thanh lịch và tinh thần trẻ trung\n Điểm nhấn cổ thủy thủ phối viền tương phản, nút bạc cùng tùng váy xếp pli tạo dấu ấn thị giác rõ ràng nhưng vẫn tinh gọn\nHàng nút trước giúp tổng thể gọn gàng, dễ mặc và dễ điều chỉnh\nChân váy xếp ly nhẹ ở gấu, tăng độ chuyển động tự nhiên khi di chuyển\nPhù hợp diện đi làm, gặp gỡ cuối tuần hoặc các dịp cần phong cách chỉn chu nhưng không cứng nhắc\nChất liệu: 75% Cotton – 25% Polyester, bề mặt đứng vừa, thoáng nhẹ, dễ giữ phom\nDễ phối cùng giày cao gót, sandal hoặc loafer cho nhiều hoàn cảnh khác nhau'),(699000.00,1,NULL,11,45,'2026-03-13 07:05:40.173014','2026-03-13 07:05:40.173014','Đầm Nữ Tay Cánh Tiên','Thiết kế dáng đầm ngắn, phom gọn gàng, tôn vòng eo và tạo hiệu ứng cân đối cho tổng thể vóc dáng\n Tay cánh tiên mềm rũ, mang lại cảm giác nữ tính, nhẹ nhàng và giúp cánh tay trông thanh thoát hơn\nChi tiết hàng nút bọc phía trước tạo điểm nhấn tinh tế, tăng chiều sâu cho thiết kế tối giản\nPhần eo chiết nhẹ, chân váy xòe vừa phải, dễ di chuyển và tạo độ bay tự nhiên khi mặc\nChất liệu 100% Polyester: bề mặt mềm mịn, nhẹ, giữ phom ổn định và ít nhăn\nPhù hợp cho nhiều hoàn cảnh: đi làm, dạo phố, hẹn hò hay các buổi gặp gỡ cần sự chỉn chu'),(749000.00,1,NULL,11,46,'2026-03-13 07:07:37.537754','2026-03-13 07:07:37.537754','Đầm Sơ Mi Dáng Midi Thắt Eo','Chất liệu 80% Polyester, 20% Rayon cho bề mặt vải mềm mịn, nhẹ và rủ tự nhiên, giữ phom ổn định khi mặc cả ngày\nThiết kế dáng sơ mi không tay, đường cắt gọn gàng, mang lại cảm giác thanh lịch và thoáng mát\nChi tiết chiết eo tinh tế, tôn dáng vừa đủ, tạo tỷ lệ cơ thể cân đối và nữ tính\nDây thắt lưng phía sau giúp dễ dàng điều chỉnh độ ôm, linh hoạt theo nhiều vóc dáng\nHàng nút trước tối giản, dễ mặc – dễ phối, phù hợp từ môi trường công sở đến những buổi dạo phố nhẹ nhàng\nGam màu trung tính trang nhã, dễ kết hợp cùng giày cao gót, sandals hoặc phụ kiện tối giản'),(749000.00,1,NULL,11,47,'2026-03-13 07:10:00.800990','2026-03-13 07:10:00.800990','Đầm Voan Tay Dài Phối Bèo','Chất liệu 100% Polyester, bề mặt voan nhẹ, rủ mềm, tạo cảm giác bay bổng và nữ tính khi mặc\n Thiết kế cổ V nhẹ, phối bèo tầng tinh tế ở phần vai và lưng sau, mang lại điểm nhấn mềm mại nhưng vẫn thanh lịch\nTay dài voan sheer, bo cổ tay gọn gàng, giúp tổng thể trang phục nhẹ nhàng và cân đối\nPhần eo bo chun nhẹ, tôn vòng eo tự nhiên, dễ mặc và thoải mái trong nhiều hoạt động\nDáng đầm suông nhẹ, chiều dài trên gối, phù hợp nhiều vóc dáng\nTông màu trắng trang nhã, dễ phối phụ kiện, phù hợp đi làm, dạo phố hoặc dự tiệc nhẹ'),(649000.00,1,NULL,11,48,'2026-03-13 07:11:39.172865','2026-03-13 07:11:39.172865','Đầm Maxi Dáng Dài Nhún Eo','Chất liệu 95% Rayon – 5% Nilon, mềm rũ, thoáng nhẹ, mang đến cảm giác thoải mái cho những ngày nắng.\nPhom dáng dài nữ tính, tạo hiệu ứng thon gọn và uyển chuyển khi di chuyển.\nThiết kế không tay hiện đại, dễ phối cùng cardigan, áo khoác mỏng hoặc phụ kiện tối giản. Nhún eo nhẹ giúp tôn vòng eo tự nhiên, tạo điểm nhấn hài hòa cho tổng thể.\nTầng váy dưới xếp rũ nhẹ, tăng độ bồng bềnh và chiều sâu cho kiểu dáng. Phần cổ thân sau xẻ giọt nước cài nút, không dây kéo tinh tế, thuận tiện khi mặc.'),(1500000.00,1,NULL,12,49,'2026-03-13 07:15:31.937763','2026-03-13 07:15:31.937763','Áo Khoác Nam Phao Dày','Áo với chất liệu 100% Nylon bền nhẹ, có khả năng chắn gió và trượt nước nhẹ, giúp bảo vệ người mặc trong thời tiết lạnh hoặc mưa phùn. Lớp chần bông miếng thủ công được hoàn thiện tỉ mỉ, giúp giữ nhiệt ổn định, mang lại cảm giác ấm áp mà vẫn đảm bảo sự linh hoạt khi vận động.\nThiết kế hiện đại với mũ có thể tháo rời tiện dụng, khóa kéo chắc chắn và phom dáng cân đối. Bề mặt vải mềm mại, dễ chịu khi mặc. Đường may tinh tế, xử lý tỉ mỉ trong từng chi tiết giúp áo giữ phom tốt và tăng độ bền khi sử dụng.\nChiếc áo là lựa chọn hoàn hảo cho mùa lạnh – không chỉ giúp giữ ấm hiệu quả mà còn mang đến phong cách năng động, hiện đại.'),(1500000.00,1,NULL,12,50,'2026-03-13 07:17:00.054067','2026-03-13 07:17:00.054067','Áo Khoác Nam Phao Dày','Áo với chất liệu 100% Polyester có bề mặt mềm mịn, dày dặn, có khả năng chắn gió và trượt nước nhẹ, giúp bảo vệ người mặc trước những cơn mưa phùn hay gió lạnh bất chợt.\nLớp chần bông gòn dày dặn bên trong mang lại khả năng giữ nhiệt vượt trội, giúp cơ thể luôn ấm áp trong những ngày đông. Kiểu dáng khoác phao cổ điển được tinh giản, khóa kéo chắc chắn và đường may tỉ mỉ, dễ dàng kết hợp với nhiều trang phục khác nhau.\nChiếc áo không chỉ là lớp bảo vệ trước thời tiết mà còn là điểm nhấn phong cách, thích hợp từ đi làm, dạo phố đến những chuyến đi xa trong mùa lạnh.'),(1100000.00,1,NULL,12,51,'2026-03-13 07:19:40.290930','2026-03-13 07:19:40.290930','Áo Khoác Nam Thời Trang','Chất liệu 100% cotton tự nhiên, mềm mịn và thấm hút mồ hôi tốt – mang lại cảm giác thoáng mát, dễ chịu suốt cả ngày dài.\nThiết kế tối giản với khoá kéo trước, form suông thoải mái, tay bo nhẹ tạo điểm nhấn hiện đại và năng động.\nMàu sắc trung tính dễ phối, kết hợp linh hoạt cùng áo thun, quần jeans hay jogger cho nhiều dịp từ đi làm đến dạo phố.'),(1100000.00,1,NULL,12,52,'2026-03-13 07:22:06.701230','2026-03-13 07:22:06.701230','Áo Khoác Nam Cá Tính','Chất liệu 100% cotton mềm mịn, thoáng mát và thân thiện với làn da, mang lại cảm giác nhẹ nhàng, dễ chịu trong suốt quá trình mặc.\nThiết kế knit mỏng, phối nhiều túi hộp trước ngực và tay áo – vừa tiện dụng vừa tạo điểm nhấn cá tính, phù hợp với những ai yêu thích sự linh hoạt và thoải mái trong từng chuyển động.\nDễ dàng kết hợp cùng áo thun, quần shorts, quần jeans hoặc jogger – lý tưởng cho các hoạt động ngoài trời, dạo phố hoặc những buổi hẹn cuối tuần mang tinh thần phóng khoáng, năng động.'),(1500000.00,1,NULL,12,53,'2026-03-13 07:25:02.896607','2026-03-13 07:25:02.896607','Áo Khoác Nam Cá Tính','Chất liệu 75% polyester, 15% rayon và 10% cotton – kết hợp giữa độ bền, khả năng giữ ấm và sự mềm mại khi chạm vào. Bề mặt vải nhẹ, không gây bí bách, giúp người mặc cảm thấy luôn thoải mái, đặc biệt phù hợp với tiết trời se lạnh hoặc những ngày chuyển mùa.\nThiết kế tay dài, cổ bẻ cổ điển, form áo suông dễ mặc. Họa tiết caro phối màu nổi bật, cùng chi tiết túi hộp hai bên ngực giúp tổng thể vừa trẻ trung, vừa hiện đại. Đường may sắc nét, khuy áo chắc chắn thể hiện sự chỉn chu trong từng chi tiết.\nDễ dàng kết hợp với áo thun trơn, áo cổ lọ hoặc layer thành khoác ngoài. Màu sắc trung tính, phù hợp với nhiều kiểu quần như jeans, khaki hay short – lý tưởng để mặc đi làm, dạo phố, cà phê hoặc du lịch.'),(900000.00,1,NULL,13,54,'2026-03-13 07:28:48.038457','2026-03-13 07:28:48.038457','Quần Tây Nam Form Vừa','Quần tây có chất liệu 64% Polyester, 25% Rayon, 8% Lyocell và 3% Spandex, mang lại bề mặt vải mềm, thoáng và có độ rũ tự nhiên. Polyester giúp quần giữ phom tốt; Rayon và Lyocell tạo cảm giác mát và nhẹ; Spandex hỗ trợ độ đàn hồi, tăng sự thoải mái khi di chuyển.\nForm dáng vừa vặn, ôm nhẹ phần hông và suông dần xuống gấu, mang lại tổng thể thanh lịch và dễ mặc. Thiết kế phù hợp cho môi trường công sở hoặc những dịp cần sự chỉn chu.\nPhần lưng được thiết kế thông minh với hai bản thun mềm co giãn ở hai bên hông, mang đến sự thoải mái cho người mặc mà vẫn giữ được phom dáng chuẩn của quần.\nCạp quần đứng phom, đường may tinh tế và túi trước – sau bố trí hợp lý giúp quần giữ dáng tốt trong suốt ngày dài. Bề mặt vải ít nhăn, thuận tiện cho việc sử dụng thường xuyên.\nDễ dàng kết hợp cùng sơ mi, polo hoặc áo thun basic tạo nên vẻ ngoài lịch lãm và nam tính.'),(850000.00,1,NULL,13,55,'2026-03-13 07:30:30.141038','2026-03-13 07:30:30.141038','Quần Tây Nam Form Vừa','Chất liệu gồm 84% Polyester 15% Viscose và 1% Spandex hạn chế nhăn, giữ phom ổn định và mang lại cảm giác thoải mái khi mặc.\nThiết kế form vừa thanh lịch, dễ mặc, tôn dáng, phù hợp với môi trường công sở hoặc những dịp cần sự chỉn chu.\nDễ kết hợp với sơ mi, polo hoặc áo vest, hoàn thiện vẻ ngoài nam tính và chuyên nghiệp.'),(800000.00,1,NULL,13,56,'2026-03-13 07:35:55.429845','2026-03-13 07:35:55.429845','Quần Tây Nam Form Ôm Vừa','Quần có chất liệu 100% Polyester Nano, vải nhẹ, ít nhăn và giữ phom tốt, phù hợp cho nhu cầu mặc hằng ngày.\nThiết kế form ôm vừa, ôm gọn phần hông và đùi, ống quần suông nhẹ xuống gấu, tạo dáng gọn gàng nhưng không bó sát, giúp người mặc thoải mái khi di chuyển hoặc ngồi lâu.\nCạp quần vừa vặn, các chi tiết đường may được xử lý gọn gàng, đảm bảo độ bền trong quá trình sử dụng.\nGam màu trung tính, dễ phối cùng áo sơ mi, polo hoặc áo thun, phù hợp cho đi làm, gặp gỡ hoặc mặc thường ngày theo phong cách lịch sự, chỉn chu.'),(800000.00,1,NULL,13,57,'2026-03-13 07:37:58.559605','2026-03-13 07:37:58.559605','Quần Tây Nam Form Ôm Vừa','Quần có chất liệu 100% Polyester Nano, vải nhẹ, ít nhăn và giữ phom tốt, phù hợp cho nhu cầu mặc hằng ngày.\nThiết kế form ôm vừa, ôm gọn phần hông và đùi, ống quần suông nhẹ xuống gấu, tạo dáng gọn gàng nhưng không bó sát, giúp người mặc thoải mái khi di chuyển hoặc ngồi lâu.\nCạp quần vừa vặn, các chi tiết đường may được xử lý gọn gàng, đảm bảo độ bền trong quá trình sử dụng.\nGam màu trung tính, dễ phối cùng áo sơ mi, polo hoặc áo thun, phù hợp cho đi làm, gặp gỡ hoặc mặc thường ngày theo phong cách lịch sự, chỉn chu.'),(850000.00,1,NULL,13,58,'2026-03-13 07:39:33.321886','2026-03-13 07:39:33.321886','Quần Tây Nam Form Ôm Vừa','Chất liệu 57% polyester, 38% rayon và 5% spandex mang lại bề mặt vải mịn, thoáng và có độ co giãn nhẹ. Quần giữ phom chuẩn, hạn chế nhăn, giúp người mặc thoải mái mà vẫn giữ được vẻ chỉnh tề.\nThiết kế form ôm vừa hiện đại, đường cắt may gọn gàng, ống đứng tinh giản tạo hiệu ứng kéo dài đôi chân. Các chi tiết túi và cạp quần được xử lý tinh tế, góp phần làm tổng thể thêm sang trọng.\nDễ dàng kết hợp cùng sơ mi hoặc blazer, quần tây mang đến diện mạo lịch lãm nơi công sở, đồng thời linh hoạt khi xuất hiện trong các buổi gặp gỡ trang trọng.'),(850000.00,1,NULL,13,59,'2026-03-13 07:41:28.320267','2026-03-13 07:41:28.320267','Quần Tây Nam Form Wide-Leg Straight','Quần tây có chất liệu 64% Polyester, 25% Rayon, 8% Lyocell và 3% Spandex, mang lại bề mặt vải mềm, thoáng và có độ rũ tự nhiên.\nThiết kế form Wide-Leg Straight với phần hông và đùi rộng rãi, ống quần suông thẳng từ trên xuống gấu. Dáng quần thoải mái, dễ cử động, đồng thời giúp che khuyết điểm chân và tạo tổng thể cân đối.\nPhần hạ đáy được thiết kế dài hơn, tăng sự thoải mái khi di chuyển. Form quần rộng nhưng vẫn giữ được nét chỉn chu đặc trưng của quần tây.\nDễ phối cùng sơ mi, áo thun hoặc polo. Phù hợp cho môi trường công sở, phong cách smart–casual và cũng thích hợp để tạo nên vẻ ngoài trẻ trung nhờ thay đổi cách phối linh hoạt.'),(499000.00,1,NULL,9,60,'2026-03-13 07:43:50.383296','2026-03-13 07:43:50.383296','Chân Váy Jeans Ngắn Cá Tính',' Chân váy jeans dáng ngắn, phom váy A nhẹ có lớp quần bảo hộ phía trong, tôn dáng nhưng vẫn tạo cảm giác thoải mái và an toàn khi di chuyển\nThiết kế tối giản, nhấn vào đường cắt và chi tiết lai tua nhẹ, mang lại tinh thần trẻ trung, năng động\nChất liệu denim có độ co giãn vừa phải, giúp váy ôm dáng tự nhiên, dễ mặc trong nhiều hoạt động hằng ngày\nGam màu jeans xanh dễ phối cùng áo thun, áo sơ mi hoặc croptop cho nhiều phong cách khác nhau\nPhù hợp diện đi chơi, dạo phố hoặc những ngày cần một outfit casual nhưng vẫn có điểm nhấn\nChất liệu: 95% Cotton, 2% Polyester, 3% Spandex'),(590000.00,1,NULL,9,61,'2026-03-13 07:45:48.747643','2026-03-13 07:45:48.747643','Chân Váy Dài Rút Dây','Chất liệu: 90% Nylon – 10% Spandex, nhẹ – thoáng – đàn hồi tốt, mang lại cảm giác thoải mái cho cả ngày dài.\nPhom dáng: Dài qua gối, rủ mềm, tạo hiệu ứng thanh thoát và che dáng khéo léo.\nThiết kế: Lưng thun kèm dây rút, dễ điều chỉnh theo vòng eo. Độ xòe vừa phải, lai cong về phía sườn, tông màu trung tính dễ phối với áo thun, áo khoác tank top cho vẻ ngoài năng động.'),(600000.00,1,NULL,4,62,'2026-03-13 12:29:34.819248','2026-03-13 12:29:34.819248','Áo Polo Nam Form Vừa','Áo polo sử dụng chất liệu 72% cotton và 28% Sorona, vải mềm, thoáng và có độ co giãn nhẹ, mang lại cảm giác thoải mái khi mặc hằng ngày.\nThiết kế form vừa, thân áo suông nhẹ, không ôm sát cơ thể. Vai áo vừa vặn, tay áo có độ rộng hợp lý, giúp tổng thể gọn gàng và dễ mặc.\nCổ polo đứng form, hàng nút được xử lý gọn gàng, giữ dáng ổn định trong quá trình sử dụng.\nGam màu trơn dễ phối, phù hợp cho đi làm, đi chơi hoặc mặc thường ngày.'),(600000.00,1,NULL,4,63,'2026-03-13 12:31:20.136997','2026-03-13 12:31:20.136997','Áo polo nam tay ngắn','Áo polo form vừa, tay ngắn có bo, lai áo xẻ tà phối dây tape dệt có tên thương hiệu, lá cổ và tay áo phối sọc nổi bật, trẻ trung. Logo John Henry được thêu tinh tế, giúp nhận diện thương hiệu.\nChất liệu 94% cotton dệt cùng 6% sợi spandex co giãn, bề mặt vải mềm mịn, thấm hút mồ hôi tốt, đem lại cảm giác nhẹ nhàng và thoải mái cho người mặc.\nMàu sắc trẻ trung, nam tính và đa dạng nhiều lựa chọn. Dễ dàng kết hợp với quần short, quần Jeans hay khaki phù hợp cho nhiều hoạt động trong ngày.'),(700000.00,1,NULL,4,64,'2026-03-13 12:33:03.248350','2026-03-13 12:33:03.248350','Áo Polo Nam Tay Ngắn Form Vừa','Áo polo có chất liệu 72% Cotton và 28% Sorona, vải mềm, thoáng và có độ co giãn nhẹ, tạo cảm giác thoải mái khi mặc trong ngày dài.\nThiết kế form vừa, thân áo suông nhẹ, không ôm sát cơ thể. Vai áo vừa vặn, tay áo có độ rộng hợp lý, giúp tổng thể gọn gàng và dễ mặc với nhiều dáng người.\nCổ polo đứng form, đường may chắc chắn, giữ phom ổn định khi sử dụng. Họa tiết sọc in đơn giản ở thân trước tạo điểm nhấn tinh tế.\nDễ phối cùng quần jeans, khaki hoặc quần shorts, phù hợp cho đi làm, đi chơi hoặc mặc hằng ngày.'),(550000.00,1,NULL,4,65,'2026-03-13 12:34:37.699316','2026-03-13 12:34:37.699316','Áo Polo Nam Tay Ngắn Form Rộng','Áo polo với chất liệu 100% Polyester, mang lại bề mặt vải nhẹ, thoáng và đàn hồi tốt. Chất liệu polyester hiện đại giúp áo giữ phom bền, hạn chế nhăn và dễ chăm sóc khi sử dụng hằng ngày. Áo ứng dụng công nghệ Wicking Free, hỗ trợ thấm hút và thoát ẩm nhanh, giúp cơ thể luôn khô thoáng khi vận động hoặc di chuyển nhiều.\nPhom dáng form rộng với thân áo suông và vai rộng, mang lại vẻ ngoài trẻ trung và thoải mái. Thiết kế tối giản với gam màu nam tính. Cổ polo đứng phom, tay áo bo nhẹ, túi ngực tinh gọn và logo thêu tinh tế mang lại tổng thể chỉn chu nhưng vẫn giữ được sự thoải mái đặc trưng của dòng classic.\nDễ dàng phối cùng quần jeans, khaki hoặc shorts, phù hợp cho phong cách casual linh hoạt, từ đi làm đến dạo phố cuối tuần.'),(700000.00,1,NULL,4,66,'2026-03-13 12:36:37.662536','2026-03-13 12:36:37.662536','Áo Polo Nam Tay Ngắn Form Vừa','Áo với chất liệu 67% Cafe, 33% Polyester giúp bề mặt vải có độ thoáng tốt, nhẹ và dễ chịu khi mặc cả ngày. Chất liệu Cafe giúp hạn chế bám mùi, khô nhanh và phù hợp cho các hoạt động ngoài trời hoặc di chuyển nhiều.\nForm vừa mang đến sự thoải mái cho chuyển động. Phần cổ bẻ đứng dáng, phối đường viền tinh tế ở mép cổ giúp tổng thể trông hiện đại hơn. Tay áo được bo nhẹ, giữ phom gọn và cân đối.\n Điểm nhấn của áo nằm ở họa tiết line chạy chéo trước ngực, kết hợp nhiều sắc độ hài hòa, mang lại cảm giác năng động và trẻ trung. Bản line thanh mảnh giúp phần thân trên trông cân đối hơn khi mặc. Đường may được hoàn thiện tỉ mỉ ở vai, nách và sống áo, đảm bảo độ bền khi sử dụng lâu dài.\nDễ dàng kết hợp áo cùng jeans, khaki hoặc shorts để có vẻ ngoài năng động và cá tính.'),(800000.00,1,NULL,5,67,'2026-03-13 12:39:46.265862','2026-03-13 12:39:46.265862','Sơ Mi Nam Tay Dài Form Ôm','Sơ mi có chất liệu 50% Bamboo và 50% Polyester, bề mặt vải mềm, thoáng và ít nhăn. Chất liệu giúp áo dễ chịu khi mặc và giữ phom ổn định trong quá trình sử dụng.\nThiết kế form ôm, gọn gàng ở vai, ngực và thân áo, tạo dáng chỉn chu nhưng không bó sát. Tay áo dài vừa vặn, phù hợp cho môi trường công sở hoặc những dịp cần phong cách lịch sự.\nÁo có túi ngực tiện dụng, logo thêu tinh tế cùng họa tiết caro nhỏ và gam màu trung tính mang lại vẻ ngoài hiện đại, dễ phối đồ.\nDễ kết hợp cùng quần tây hoặc khaki, phù hợp cho môi trường công sở lịch sự và chuyên nghiệp hoặc có thể phối cùng quần jeans để tạo vẻ ngoài trẻ trung, năng động.'),(700000.00,1,NULL,5,68,'2026-03-13 12:42:16.063654','2026-03-13 12:42:16.063654','Áo Sơ Mi Nam Tay Ngắn Form Comfort Fit','Áo có chất liệu 50% Bamboo và 50% Polyester, mang đến sự mềm mại, thoáng mát và khả năng thấm hút tốt. Chất liệu bền chắc, ít nhăn và dễ chăm sóc, giúp áo luôn giữ phom dáng chỉn chu trong nhiều hoàn cảnh.\nThiết kế form Comfort Fit – ôm vừa vặn nhưng vẫn thoải mái, mang lại sự gọn gàng và tính linh hoạt, dễ ứng dụng. Gam màu đặc sắc kết hợp họa tiết nhỏ tinh tế tạo nên diện mạo hiện đại, lịch lãm và khác biệt.\nChiếc áo dễ phối cùng quần khaki, jeans hay quần tây, thích hợp từ công sở đến dạo phố. Một item linh hoạt cho phong cách nam tính, thoải mái và chuẩn mực.'),(700000.00,1,NULL,5,69,'2026-03-13 12:44:06.464404','2026-03-13 12:44:06.464404','Áo sơ mi nam tay dài phối màu','Áo sơ mi nam kiểu dáng classic, form vừa tay dài, vạt bầu và có thêu logo thương hiệu trước ngực. Kẻ ngang phối màu tinh tế tạo ấn tượng cho trang phục.\nThành phần chất liệu: 60% cotton USA, 40% Polyester với bề mặt vải mềm mịn giúp sản phẩm đàn hồi tốt, thấm hút mồ hôi, mang lại cho người mặc cảm giác thoải mái và thoáng mát\nNam tính, năng động khi phối cùng quần jeans hoặc phối cùng quần tây/khaki để sở hữu vẻ ngoài lịch lãm và chỉnh chu chốn công sở.'),(700000.00,1,NULL,5,70,'2026-03-13 12:46:41.969211','2026-03-13 12:46:41.969211','Áo Sơ Mi Nam Tay Ngắn Form Vừa','Chất liệu 48% Bamboo, 48% Microfiber và 4% Spandex mang lại sự mềm mại, thoáng khí và co giãn nhẹ, giúp bạn cảm thấy thoải mái suốt ngày dài.\nÁo sơ mi tay ngắn, form vừa vặn, với thiết kế hiện đại, tôn lên nét thanh lịch và trẻ trung.\nDễ dàng phối hợp với quần tây hoặc khaki, là lựa chọn hoàn hảo cho các dịp từ công sở đến dạo phố, tạo phong cách năng động và lịch sự.'),(700000.00,1,NULL,5,71,'2026-03-13 12:48:37.897914','2026-03-13 12:48:37.897914','Áo Sơ Mi Nam Form Ôm Tay Ngắn','Chất liệu 86% Tencel, 10% Bamboo, 4% Spandex mang lại sự mềm mại, thoáng khí và co giãn nhẹ, tạo cảm giác thoải mái suốt cả ngày.\nThiết kế form ôm tôn dáng, họa tiết đặc sắc kết hợp logo thêu tinh tế, mang đến vẻ ngoài thời thượng và cuốn hút.\nDễ dàng phối cùng quần jeans hoặc quần tây, phù hợp cho cả những buổi gặp gỡ năng động lẫn môi trường công sở hiện đại.'),(1950000.00,1,NULL,10,72,'2026-03-13 12:51:29.905578','2026-03-13 12:51:29.905578','Áo Blazer Nam Dài Tay Lịch Lãm','Áo blazer được thiết kế với form không quá rộng , có độ ôm vừa phải, phù hợp với mọi dáng người. Thiết kế cổ điển pha lẫn với hiện đại với 2 khuy cài trước áo, 2 khuy ở tay áo, 2 đường xẻ tà, độn vai vừa phải tạo vẻ ngoài cứng cáp, lịch lãm.\n\n- Chất liệu vải nano với các tính năng như: Thấm hút vượt trội, Nhanh khô, Có độ co dãn nhẹ tạo sự thoải mái khi cử động, Chống tia UV bảo vệ làn da khỏi ánh nắng mặt trời gay gắt. Đặc biệt chức năng không nhăn tự nhiên giúp cho các cử động nhiều ở khủy tay hay sau lưng khi ngồi sẽ không bị nhăn nhiều, vẫn giữ đc sự chỉn chu suốt 1 ngày dài.\nÁo được ứng dụng công nghệ may tiên tiến và sản xuất tại nhà máy lớn, có máy móc hiện đại, chuyên dụng , đạt các tiêu chuẩn của quốc tế về may áo blazer.\nChiếc áo không có lớp lót trong thay vào đó đề cao sự thoải mái, thoáng mát và sự chỉn chu, kỹ lưõng trong đường may\nPhối cùng quần tây hoặc quần khaki để có vẻ ngoài chỉn chu, hoặc linh hoạt phối cùng quần jeans để có một outfit trẻ trung hơn.'),(1500000.00,1,NULL,12,73,'2026-03-13 12:54:37.988761','2026-03-13 12:54:37.988761','Áo Khoác Nam Phong Cách','Được làm từ chất liệu 100% Polyester, áo có bề mặt vải trơn và ít nhăn. Với 2 lớp mỏng nhẹ, áo giúp giữ nhiệt tốt nhưng vẫn tạo được cảm giác thoải mái và thoáng mát cho người mặc.\nÁo dễ làm sạch và bảo quản, có khả năng giữ nhiệt & cản gió. Đồng thời có tính năng giúp chồng nắng và trượt nước nhẹ, thích hợp sử dụng trong mọi thời tiết.\nVới gam màu trung tính, đơn giản nhưng không kém phần trẻ trung và thời trang, áo có thể kết hợp cùng với nhiều loại trang phục khác nhau, dễ dàng ứng dụng mặc đi chơi, đi làm hoặc dạo phố.'),(1200000.00,1,NULL,12,74,'2026-03-13 12:56:01.866153','2026-03-13 12:56:01.866153','Áo Khoác Nam Phong Cách','Áo khoác với chất liệu 97% cotton và 3% spandex mang lại sự mềm mại, thoải mái với độ co giãn nhẹ, giúp người mặc cảm thấy dễ chịu trong mọi hoạt động.\nÁo có thiết kế trẻ trung, hiện đại với gam màu cơ bản dễ phối đồ, tôn lên vẻ ngoài năng động và thời trang. Áo có 2 túi trước ngực tiện lợi cùng đường may tinh tế, sắc nét mang đến sự chỉn chu và tự tin.\nDễ dàng kết hợp với áo thun, sơ mi hay quần jeans, là lựa chọn hoàn hảo cho cả những buổi dạo phố hay đi làm, mang đến phong cách cá tính và trẻ trung.'),(1500000.00,1,NULL,12,75,'2026-03-13 12:57:46.847025','2026-03-13 12:57:46.847025','Áo Khoác Nam Phong Cách','Chất liệu vải khaki nhung với 72% Polyester, 25% Nylon, và 3% Spandex mang đến độ bền và co giãn nhẹ, đảm bảo sự thoải mái và giữ form tốt khi mặc.\nÁo khoác có thiết kế thời trang, form vừa vặn, với túi hai bên tiện lợi, tạo nên vẻ ngoài hiện đại và sang trọng. Áo phù hợp với thời tiết se se lạnh.\nDễ dàng kết hợp với nhiều loại trang phục, từ công sở đến dạo phố, mang đến phong cách thanh lịch và thời thượng.'),(349000.00,1,NULL,9,76,'2026-03-13 13:00:34.583911','2026-03-13 13:00:34.583911','Chân Váy Ngắn Bất Đối Xứng','Chất liệu: 95% Polyester, 5% Spandex – co giãn nhẹ, giữ phom tốt, hạn chế nhăn\nThiết kế: Dáng váy form A ngắn bất đối xứng tạo điểm nhấn thời trang hiện đại\nMàu sắc: Đen cơ bản – dễ phối với nhiều kiểu áo và phụ kiện\nPhù hợp: Công sở, sự kiện, hẹn hò hay dạo phố đều nổi bật\nForm dáng: Ôm nhẹ phần hông, tôn dáng và tạo hiệu ứng chân thon dài'),(399000.00,1,NULL,9,77,'2026-03-13 13:02:01.052099','2026-03-13 13:02:01.052099','Chân Váy Freelancer','Chất liệu 56% Rayon, 34% Nilon, 10% Linen, mang đến sự mềm mại, thoáng mát nhưng vẫn có độ đứng phom vừa đủ, phù hợp với những ngày hè.\nThiết kế bất đối xứng với đường cắt xếp lớp nhẹ nhàng, tạo điểm nhấn tinh tế và tôn dáng.\nGam màu trung tính thanh lịch, dễ dàng phối cùng sơ mi hoặc áo thun để biến hóa đa dạng phong cách.\nCạp váy vừa vặn, tạo cảm giác thoải mái khi mặc cả ngày dài.'),(599000.00,1,NULL,9,78,'2026-03-13 13:03:19.114600','2026-03-13 13:03:19.114600','Chân Váy Midi Xếp Nhún','Chất liệu: 95% Polyester, 5% Spandex – giữ phom tốt, co giãn nhẹ, thoải mái khi di chuyển.\nThiết kế dáng midi dài qua gối, tôn dáng và mang lại sự thanh thoát.\nChi tiết xếp nhún tinh tế, tạo điểm nhấn mềm mại và nữ tính.\nCạp cao gọn gàng, dễ phối cùng sơ mi, áo thun hay croptop.\nGam đen kinh điển, dễ phối đồ và phù hợp nhiều hoàn cảnh.'),(399000.00,1,NULL,9,79,'2026-03-13 13:04:32.272772','2026-03-13 13:04:32.272772','Mini Skirt Basic Màu Beige','Chất liệu: 100% polyester bền màu, không nhăn và giữ phom tốt.\nChân váy kaki co giãn nhẹ, cạp cao tôn dáng và tạo hiệu ứng chân thon dài.\nThiết kế trơn tinh giản, dễ phối cùng áo thun, sơ mi hay polo.\nGam màu beige trung tính, hợp nhiều tone da, dễ ứng dụng nhiều dịp.'),(399000.00,1,NULL,7,80,'2026-03-13 13:06:44.709025','2026-03-13 13:06:44.709025','Áo Blouse Nữ Bèo Gấu','Thiết kế áo blouse sát nách, phom suông, mang lại cảm giác thanh thoát và nữ tính khi mặc\nĐiểm nhấn bèo gấu mềm mại, tạo độ rủ nhẹ và tăng nét duyên dáng cho tổng thể\nChất liệu 100% Polyester nhẹ, thoáng, bề mặt mịn, giúp áo giữ phom tốt và dễ chăm sóc\nGam màu sáng, dễ phối cùng quần tây, chân váy hoặc jeans cho nhiều hoàn cảnh khác nhau\nPhù hợp mặc đi làm, dạo phố hoặc những ngày cần một outfit nhẹ nhàng nhưng vẫn chỉn chu'),(449000.00,1,NULL,7,81,'2026-03-13 13:08:10.288078','2026-03-13 13:08:10.288078','Áo Blouse Nữ Tay Bồng','Áo Blouse tay phồng với điểm nhấn dây rút điệu đà \nChất liệu 100% Polyester in hoa chìm, khả năng chống nhăn tốt \nDễ dàng phối với các kiểu chân váy, quần jeans… mang đến vẻ nữ tính nhưng vẫn trẻ trung, năng động.'),(174500.00,1,NULL,7,82,'2026-03-13 13:11:10.753408','2026-03-13 13:11:10.753408','Áo kiểu nữ sát nách cổ lọ','Áo kiểu sát nách, thiết kế cách điệu ấn tượng. Mang đến vẻ ngoài thanh lịch nhưng vẫn nữ tính, điệu đà cho người mặc.\nChất liệu lụa cao cấp nhập khẩu với bề mặt mềm mịn, ít nhăn, bền màu, đem lại cảm giác nhẹ nhàng và thoải mái.\nMàu sắc đơn giản, thời trang, dễ phối đồ. Phối cùng chân váy mang lại vể ngoài trang nhã hay linh hoạt phối cùng quần tây, quần jeans,.. tạo dấu ấn thời trang cá nhân'),(749000.00,1,NULL,11,83,'2026-03-13 13:13:47.544582','2026-03-13 13:13:47.544582','Đầm Dài Xếp Ly',' Chất liệu 91% Rayon – 9% Spandex: mềm mại, thoáng nhẹ, có độ co giãn vừa phải, mang lại cảm giác dễ chịu khi mặc suốt ngày dài.\nDáng đầm dài, phom chữ A nhẹ: giúp tôn dáng tự nhiên, tạo độ rủ mềm mại và cân đối tổng thể.\nThiết kế xếp ly tinh tế phần thân trên: tạo điểm nhấn nữ tính, tăng chiều sâu cho phom dáng mà không làm mất đi sự tối giản.\nPhần túi nhún thun hai bên: giúp định hình vòng eo gọn gàng, mang lại vẻ ngoài thanh lịch nhưng vẫn thoải mái khi di chuyển.\nThiết kế sát nách hiện đại: dễ layer hoặc mặc đơn, phù hợp cho nhiều hoàn cảnh từ công sở đến dạo phố.\nGam màu trung tính: dễ phối phụ kiện, phù hợp với nhiều phong cách và tone da.'),(749000.00,1,NULL,11,84,'2026-03-13 13:15:24.111965','2026-03-13 13:15:24.111965','Đầm Voan Tay Dài Phối Bèo','Chất liệu 100% Polyester, bề mặt voan nhẹ, rủ mềm, tạo cảm giác bay bổng và nữ tính khi mặc\n Thiết kế cổ V nhẹ, phối bèo tầng tinh tế ở phần vai và lưng sau, mang lại điểm nhấn mềm mại nhưng vẫn thanh lịch\nTay dài voan sheer, bo cổ tay gọn gàng, giúp tổng thể trang phục nhẹ nhàng và cân đối\nPhần eo bo chun nhẹ, tôn vòng eo tự nhiên, dễ mặc và thoải mái trong nhiều hoạt động\nDáng đầm suông nhẹ, chiều dài trên gối, phù hợp nhiều vóc dáng\nTông màu trắng trang nhã, dễ phối phụ kiện, phù hợp đi làm, dạo phố hoặc dự tiệc nhẹ'),(599000.00,1,NULL,11,85,'2026-03-13 13:16:48.447710','2026-03-13 13:16:48.447710','Đầm Xòe Tay Phồng','Chất liệu: 86% Tencel, 14% Polyester – mềm mại, thoáng khí, mang lại cảm giác mát nhẹ và thoải mái khi mặc.\nThiết kế cổ tròn viền bèo nhún, tôn lên nét nữ tính và tinh tế.\nTay phồng nhẹ nhàng, tạo điểm nhấn duyên dáng, mang hơi thở cổ điển hiện đại.\nForm váy xòe nhẹ, lai bất đối xứng, mang đến sự uyển chuyển và độc đáo trong từng bước đi.\nGam màu kem dịu dàng, dễ phối cùng phụ kiện để hoàn thiện phong cách thanh lịch.'),(649000.00,1,NULL,11,86,'2026-03-13 13:19:57.341851','2026-03-13 13:19:57.341851','Đầm Nữ Dáng Xòe Cổ Trụ Thanh Lịch','Thiết kế cổ trụ gài nút, mang đến vẻ đẹp thanh lịch và hiện đại.\nDáng xòe nhẹ nhàng, kết hợp chi tiết bo eo thun tạo sự thoải mái, tôn lên vóc dáng một cách tinh tế.\nTay dài với phần cổ tay gài nút, phù hợp cho cả thời tiết se lạnh hoặc những ngày nắng nhẹ.\nChất liệu cao cấp: 86% Tencel mềm mại, thoáng mát; 14% Polyester bền đẹp, giữ form tốt.\nTông màu nhẹ nhàng, dễ dàng phối cùng giày cao gót hoặc sandal để hoàn thiện phong cách thanh lịch.\nPhù hợp cho nhiều dịp: đi làm, dạo phố hoặc tham dự các buổi tiệc nhẹ.'),(800000.00,1,NULL,13,87,'2026-03-13 13:21:51.391601','2026-03-13 13:21:51.391601','Quần Tây Nam Form Ôm Vừa','Chất liệu 100% Polyester Nano nhẹ, bền, hạn chế nhăn và giữ form tốt, mang lại cảm giác mát mẻ, linh hoạt khi di chuyển.\nThiết kế form ôm vừa hiện đại, đứng dáng, ôm nhẹ phần hông, ống suông vừa phải, tạo nên tổng thể gọn gàng và chuyên nghiệp.\nMàu sắc trung tính dễ phối, lý tưởng khi kết hợp cùng sơ mi, áo polo hoặc blazer, phù hợp cho môi trường công sở, sự kiện hay gặp gỡ đối tác.'),(800000.00,1,NULL,13,88,'2026-03-13 13:23:21.865614','2026-03-13 13:23:21.865614','Quần Tây Nam Form Ôm Vừa','Quần tây với chất liệu 100% Polyester Nano hạn chế nhăn, giữ phom tốt. Bề mặt mềm mại, thoáng khí, đem lại cảm giác thoải mái suốt ngày dài.\nForm ôm vừa giúp tôn dáng, mang đến vẻ ngoài chỉn chu, chuyên nghiệp. Đường may sắc nét, đảm bảo sự gọn gàng và tinh tế.\nDễ dàng kết hợp cùng áo sơ mi, áo polo hoặc blazer cho phong cách công sở lịch lãm.');
